CREATE FUNCTION cmd_reject_recon_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Recon receipts are immutable'; END $$;
CREATE TRIGGER cmd_recon_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_recon_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_recon_mutation();
CREATE FUNCTION cmd_validate_recon_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; BEGIN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>(SELECT skill_rule_id FROM rule_recon_mechanic WHERE rule_id=NEW.operation_rule_id) OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Recon receipt does not match its task'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_recon_receipt_valid AFTER INSERT ON cmd_recon_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_recon_receipt();
